import{j as e}from"./index-Cb5sh8pD.js";import{a as l}from"./TheoryTable-CAJX0pr7.js";function n({n:i,q:t,children:s}){return e.jsxs("div",{style:{margin:"20px 0",paddingBottom:18,borderBottom:"1px solid var(--border-color)"},children:[e.jsxs("div",{style:{display:"flex",gap:10,alignItems:"flex-start",marginBottom:8},children:[e.jsx("span",{style:{flexShrink:0,width:24,height:24,borderRadius:"50%",background:"var(--accent-lime)",color:"#0a0a14",fontSize:12,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center",marginTop:2},children:i}),e.jsx("p",{style:{margin:0,fontWeight:700,color:"var(--text-primary)",fontSize:16},children:t})]}),e.jsx("div",{style:{marginLeft:34,color:"var(--text-secondary)",fontSize:14.5,lineHeight:1.75},children:s})]})}function r({title:i}){return e.jsx("h2",{className:"theory-heading-2",children:i})}function a(){return e.jsxs("div",{className:"theory-container",children:[e.jsxs("section",{className:"theory-section",children:[e.jsx("h1",{className:"theory-title",children:"Вопросы с собеседования: Кибербезопасность"}),e.jsx("p",{className:"theory-subtitle",children:"Трек: Кибербезопасность"}),e.jsx("p",{className:"theory-date",children:"23 июля 2026"}),e.jsx("p",{children:"Тренировка на самых популярных вопросах для собеседований на позиции в сфере информационной безопасности. Первый блок — базовые понятия и виды атак. Второй блок — защита, шифрование и практика пентеста. Формат — вопрос и развёрнутый ответ."})]}),e.jsxs("section",{className:"theory-section",children:[e.jsx(r,{title:"Часть 1. Базовые понятия и виды атак"}),e.jsx(n,{n:1,q:"Что такое кибербезопасность?",children:"Область знаний и практик, направленных на защиту компьютерных систем, сетей и данных от несанкционированного доступа, повреждения или кражи. Включает как технические меры (шифрование, firewall), так и организационные (политики доступа, обучение сотрудников)."}),e.jsx(n,{n:2,q:"Что такое триада CIA?",children:"Три базовых свойства защищённой информации: Confidentiality (конфиденциальность — доступ только у тех, кому положено), Integrity (целостность — данные не изменены незаметно и без разрешения), Availability (доступность — данные и системы доступны легитимным пользователям, когда это нужно)."}),e.jsx(n,{n:3,q:"В чём разница между уязвимостью, эксплойтом и угрозой?",children:"Уязвимость — слабое место в системе (ошибка в коде, неверная настройка). Эксплойт — конкретный код или приём, который использует эту уязвимость для атаки. Угроза — потенциальный источник вреда (человек, программа, событие), который может воспользоваться уязвимостью через эксплойт."}),e.jsx(n,{n:4,q:"Что такое фишинг?",children:"Заманивание жертвы на поддельный ресурс или заставление её выполнить действие (перейти по ссылке, открыть вложение), выдавая себя за доверенный источник, чтобы выманить логин, пароль или другие конфиденциальные данные."}),e.jsx(n,{n:5,q:"Что такое SQL-инъекция?",children:"Атака, при которой злоумышленник вставляет вредоносный SQL-код во входные данные формы или запроса, и если приложение не экранирует пользовательский ввод, этот код выполняется базой данных как часть «легитимного» запроса — позволяя красть или изменять данные."}),e.jsx(n,{n:6,q:"Что такое XSS (межсайтовый скриптинг)?",children:"Уязвимость, при которой злоумышленник внедряет вредоносный JavaScript-код на страницу, который затем выполняется в браузере других пользователей, посещающих эту страницу — позволяя красть cookies, токены сессии или выполнять действия от имени жертвы."}),e.jsx(n,{n:7,q:"Что такое CSRF (межсайтовая подделка запроса)?",children:"Атака, при которой пользователя, уже авторизованного на сайте, обманом заставляют выполнить нежелательное действие (например, перевод денег) через скрытый запрос с другого сайта — браузер автоматически подставляет cookies сессии, и сервер думает, что запрос легитимен."}),e.jsx(n,{n:8,q:"Что такое DDoS-атака?",children:"Distributed Denial of Service — атака, при которой множество устройств (часто заражённых, объединённых в ботнет) одновременно отправляют огромное количество запросов серверу, перегружая его так, что он не может обслуживать легитимных пользователей."}),e.jsx(n,{n:9,q:"Что такое социальная инженерия?",children:"Манипуляция человеком (а не технической системой), чтобы заставить его раскрыть информацию или выполнить нужное атакующему действие — через давление на эмоции: срочность, страх, авторитет, доверие."}),e.jsx(n,{n:10,q:"Что такое zero-day уязвимость?",children:"Уязвимость, о которой ещё не знает производитель ПО (и поэтому нет патча/исправления) — либо злоумышленники узнали о ней раньше разработчиков и уже используют её на момент обнаружения («ноль дней» на исправление)."}),e.jsx(n,{n:11,q:"Что такое ransomware (программа-вымогатель)?",children:"Вредоносная программа, которая шифрует файлы жертвы или блокирует доступ к системе, а затем требует выкуп (обычно в криптовалюте) за восстановление доступа."}),e.jsx(n,{n:12,q:"Что такое атака «человек посередине» (Man-in-the-Middle)?",children:"Атака, при которой злоумышленник встраивается между жертвой и легитимным сервисом, перехватывая и потенциально изменяя трафик между ними, оставаясь незамеченным для обеих сторон — часто происходит в незащищённых публичных Wi-Fi сетях."}),e.jsx(l,{title:"Совет по подготовке",children:"На собеседовании по кибербезопасности часто просят не просто дать определение атаки, а объяснить, как от неё защититься на практике. К каждому виду атаки в этом списке держи в голове хотя бы одну конкретную меру защиты."})]}),e.jsxs("section",{className:"theory-section",children:[e.jsx(r,{title:"Часть 2. Защита, шифрование и пентест"}),e.jsx(n,{n:13,q:"В чём разница между симметричным и асимметричным шифрованием?",children:"Симметричное шифрование использует один и тот же ключ и для шифрования, и для расшифровки — быстрее, но требует безопасно передать ключ обеим сторонам заранее. Асимметричное использует пару ключей — открытый (для шифрования) и закрытый (для расшифровки) — не требует предварительного обмена секретом, но работает медленнее."}),e.jsx(n,{n:14,q:"Чем хеширование отличается от шифрования?",children:"Шифрование обратимо: зашифрованные данные можно расшифровать обратно исходным ключом. Хеширование необратимо: из хеша нельзя восстановить исходные данные, оно используется для проверки целостности и безопасного хранения паролей, а не для последующего восстановления исходного значения."}),e.jsx(n,{n:15,q:"Зачем нужна соль (salt) при хешировании паролей?",children:"Соль — случайная строка, добавляемая к паролю перед хешированием. Она гарантирует, что одинаковые пароли у разных пользователей дают разные хеши, что защищает от атак по заранее посчитанным таблицам хешей (rainbow tables) и делает подбор паролей значительно дороже для атакующего."}),e.jsx(n,{n:16,q:"Что такое двухфакторная аутентификация (2FA)?",children:"Дополнительный уровень защиты входа в аккаунт: помимо пароля (то, что пользователь знает) требуется второй фактор — например, код из приложения или SMS (то, что у пользователя есть). Даже если пароль украден, без второго фактора войти в аккаунт не получится."}),e.jsx(n,{n:17,q:"Что такое межсетевой экран (firewall)?",children:"Система (программная или аппаратная), которая контролирует сетевой трафик между разными сегментами сети (например, между интернетом и внутренней сетью компании) по заданным правилам, разрешая или блокируя соединения на основе адресов, портов и протоколов."}),e.jsx(n,{n:18,q:"Что такое VPN и как он защищает пользователя?",children:"Virtual Private Network — технология, создающая зашифрованный туннель между устройством пользователя и VPN-сервером. Весь трафик внутри туннеля шифруется, что защищает от перехвата в незащищённых сетях (например, публичном Wi-Fi) и скрывает реальный IP-адрес пользователя от конечного сайта."}),e.jsx(n,{n:19,q:"В чём разница между IDS и IPS?",children:"IDS (Intrusion Detection System) обнаруживает подозрительную активность в сети и оповещает администратора, но сама не блокирует её. IPS (Intrusion Prevention System) не только обнаруживает, но и автоматически блокирует подозрительный трафик в реальном времени."}),e.jsx(n,{n:20,q:"Что такое принцип наименьших привилегий (least privilege)?",children:"Правило, по которому пользователю, программе или процессу дают только тот минимальный набор прав доступа, который необходим для выполнения их задачи — не больше. Снижает ущерб в случае компрометации учётной записи или программы."}),e.jsx(n,{n:21,q:"Что такое OWASP Top 10?",children:"Регулярно обновляемый список десяти самых критичных категорий уязвимостей веб-приложений, составляемый сообществом OWASP (Open Worldwide Application Security Project) — используется как ориентир при проверке безопасности веб-приложений (в него входят, например, инъекции, некорректный контроль доступа, неправильная конфигурация безопасности)."}),e.jsx(n,{n:22,q:"Что такое пентест (penetration testing)?",children:"Санкционированная имитация реальной атаки на систему, проводимая специалистом (пентестером) с разрешения владельца системы, чтобы найти уязвимости раньше настоящих злоумышленников и дать рекомендации по их устранению."}),e.jsx(n,{n:23,q:"Что такое SIEM-система?",children:"Security Information and Event Management — система, которая собирает логи и события безопасности со всей инфраструктуры компании в одном месте, автоматически коррелирует их и помогает быстро обнаруживать подозрительные паттерны, которые были бы незаметны при просмотре логов каждой системы по отдельности."}),e.jsx(n,{n:24,q:"Как объяснить руководству, зачем компании нужна кибербезопасность?",children:"Через риски и деньги, а не термины: утечка данных клиентов ведёт к штрафам и потере доверия, простой из-за атаки — к прямым финансовым потерям, а инвестиции в базовую защиту (обновления, резервные копии, обучение сотрудников) обычно многократно дешевле, чем последствия одного успешного инцидента."})]})]})}export{a as default};
